def _codes(secret):
    return "[" + ",".join(str(ord(c)) for c in secret) + "]"

def _scan(payload):
    tmpd = tempfile.mkdtemp(prefix="w452_scan_")
    try:
        code = (
            "import os,sys;"
            "os.environ.setdefault('GOV_DEPLOYMENT_MODE','staging');"
            "os.environ.setdefault('GOV_LOG_KEY','00'*32);"
            "sys.path.insert(0," + repr(REPO_ROOT) + ");"
            "sys.path.insert(0," + repr(os.path.join(REPO_ROOT, "tests")) + ");"
            "from gov.dlp import find_credential;"
            "r=find_credential(" + repr(payload) + ");"
            "print('VERDICT:'+('HIT' if r else 'MISS'))"
        )
        env = dict(os.environ)
        env["TMPDIR"] = tmpd
        r = subprocess.run([sys.executable, "-c", code], env=env,
                           capture_output=True, text=True, timeout=180)
        for line in (r.stdout or "").strip().split("\n"):
            if line.startswith("VERDICT:"):
                return line[len("VERDICT:"):]
        return "ERR"
    finally:
        shutil.rmtree(tmpd, ignore_errors=True)

def _check(t):
    tmpd = tempfile.mkdtemp(prefix="w452_check_")
    try:
        code = (
            "import os,sys;"
            "os.environ.setdefault('GOV_DEPLOYMENT_MODE','staging');"
            "os.environ.setdefault('GOV_LOG_KEY','00'*32);"
            "sys.path.insert(0," + repr(REPO_ROOT) + ");"
            "sys.path.insert(0," + repr(os.path.join(REPO_ROOT, "tests")) + ");"
            "from gov.instruction_provenance import instruction_shaped;"
            "r=instruction_shaped(" + repr(t) + ");"
            "print('VERDICT:'+('FLAG' if r else 'QUIET'))"
        )
        env = dict(os.environ)
        env["TMPDIR"] = tmpd
        r = subprocess.run([sys.executable, "-c", code], env=env,
                           capture_output=True, text=True, timeout=120)
        for line in (r.stdout or "").strip().split("\n"):
            if line.startswith("VERDICT:"):
                return line[len("VERDICT:"):]
        return "ERR"
    finally:
        shutil.rmtree(tmpd, ignore_errors=True)

_INCIDENTAL_CLOSED_DEC_119 = {3093}
_INCIDENTAL_CLOSED_PROV_119 = set(range(3446, 3456)) | set(range(3457, 3461))

def _dec_job(item):
    num, expr, want = item
    p20 = (BUILD_T + "var U=" + expr + ";var RESULT=U;").replace("{I}", _codes(SECRET20))
    p40 = (BUILD_T + "var U=" + expr + ";var RESULT=U;").replace("{I}", _codes(SECRET40))
    v20 = _scan(p20)
    v40 = _scan(p40)
    ok = (v20 == want and v40 == want)
    print("F%d decoder: %s/%s want=%s %s" % (num, v20, v40, want, "OK" if ok else "FAIL"))
    return ok

def _dec_custom_job(item):
    num, tmpl, want = item
    p20 = tmpl.replace("{I}", _codes(SECRET20))
    p40 = tmpl.replace("{I}", _codes(SECRET40))
    v20 = _scan(p20)
    v40 = _scan(p40)
    ok = (v20 == want and v40 == want)
    print("F%d decoder-custom: %s/%s want=%s %s" % (num, v20, v40, want, "OK" if ok else "FAIL"))
    return ok

def _prov_job(item):
    num, carrier, want = item
    v = _check(carrier)
    ok = (v == want)
    print("F%d prov: %s want=%s %s" % (num, v, want, "OK" if ok else "FAIL"))
    return ok

def main():
    jobs_dec = []
    for num, expr in DECODER_NEW_120:
        jobs_dec.append((num, expr, "MISS"))
    jobs_custom = [(num, tmpl, "MISS") for num, tmpl in DECODER_CUSTOM_120]
    jobs_prov = [(num, carrier, "QUIET") for num, carrier in PROV_NEW_120]
    # carried round-119 decoder
    for num, expr in _prev.DECODER_NEW:
        want = "HIT" if num in _INCIDENTAL_CLOSED_DEC_119 else "MISS"
        jobs_dec.append((num, expr, want))
    for num, tmpl in _prev.DECODER_CUSTOM_NEW:
        jobs_custom.append((num, tmpl, "MISS"))
    for num, carrier in _prev.PROV_NEW:
        want = "FLAG" if num in _INCIDENTAL_CLOSED_PROV_119 else "QUIET"
        jobs_prov.append((num, carrier, want))
    # carried round-118 (closed by wave-451 lanes)
    for num, expr in _prev.CARRIED_DEC:
        jobs_dec.append((num, expr, "HIT"))
    for num, carrier in _prev.CARRIED_PROV:
        jobs_prov.append((num, carrier, "FLAG"))
    fails = 0
    total = 0
    with ThreadPoolExecutor(max_workers=6) as ex:
        for ok in ex.map(_dec_job, jobs_dec):
            total += 1
            if not ok:
                fails += 1
        for ok in ex.map(_dec_custom_job, jobs_custom):
            total += 1
            if not ok:
                fails += 1
        for ok in ex.map(_prov_job, jobs_prov):
            total += 1
            if not ok:
                fails += 1
    jv = _scan("the quick brown fox jumps over the lazy dog")
    pv = _check("The weather is pleasant today with clear skies.")
    print("controls: junk=%s prose=%s" % (jv, pv))
    if jv != "MISS" or pv != "QUIET":
        fails += 1
    print("total pins checked: %d, failures: %d" % (total, fails))
    print("HELD" if fails == 0 else "FAILURES: %d" % fails)
    return 0 if fails == 0 else 1

if __name__ == "__main__":
    sys.exit(main())
